join public.card_definitions d on d.code = k.code
on conflict (definition_id) do nothing;

do $$
begin
  if (select count(*) from public.card_definitions d join public.combat_kits k on k.definition_id = d.id
      where d.code in ('P003', 'P005', 'P007', 'P008', 'P009', 'P010', 'P012', 'P013', 'P014', 'P018', 'P019', 'P022', 'P024', 'P062', 'P065', 'P081', 'P083', 'P084', 'P093', 'P095', 'P096', 'P150', 'P153', 'P155', 'P197')) <> 25 then
    raise exception 'a character of the first batch has no kit';
  end if;
end $$;
